#!/usr/bin/env node
/*
 * Safe native WebView bundle synchronizer.
 *
 * The browser/PWA entry files in public/ intentionally contain Web-only
 * surfaces (ambient lighting, Web notifications, Web View Transitions, and
 * desktop download/motion UI). Capacitor native bundles use the filtered
 * entry files under native-shell/<platform>/public instead of copying those
 * files wholesale from public/.
 *
 * Shared static assets are copied from public/ through an explicit allowlist.
 * Cordova bridge files are generated by Capacitor and are preserved.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const WEB = path.join(ROOT, "public");
const CHECK_ONLY = process.argv.includes("--check");

const PLATFORMS = [
  { name: "android", destination: path.join(ROOT, "android/app/src/main/assets/public") },
  { name: "ios", destination: path.join(ROOT, "ios/App/App/public") },
];

const ENTRY_FILES = ["index.html", "app.js", "styles.css"];
const PRESERVE_FILES = new Set(["cordova.js", "cordova_plugins.js"]);

// Deliberately explicit: a newly added Web-only asset must be reviewed before
// it can enter a native bundle.
const SAFE_SHARED_PATHS = [
  "_headers",
  "_redirects",
  "animations",
  "apple-watch-like.json",
  "apple-watch-lottie-data.js",
  "assets/mood-doodles-v1.webp",
  "cover-default.jpg",
  "covers",
  "logo.png",
  "logo.svg",
  "lottie.min.js",
  "manifest.json",
  "material-symbols-outlined.woff2",
  "meta.js",
  "privacy.html",
  "sw.js",
  "terms.html",
];

// These markers are intentionally stronger than a runtime guard. Their
// presence in a native entry bundle means an unapproved Web-only surface was
// mixed into the filtered native package. The notification/profile controls
// and Smart Mood Mix are explicitly approved native Home surfaces and therefore
// are not markers.
const WEB_ONLY_MARKERS = [
  'id="ambientLight"',
  "function extractAmbientPalette(",
  "function paintHomeTasteSurface()",
  "function runWebViewTransition(",
  "function canRunWebViewTransition()",
  "function downloadButtonState(",
  "function retryDownload(",
  "web-content-resolved",
  "web-utility-modal",
  "download-progress-ring",
  "data-web-nav-direction",
  "muchi-artwork",
];

function exists(file) {
  return fs.existsSync(file);
}

function read(file) {
  return fs.readFileSync(file, "utf8");
}

function listFiles(root) {
  if (!exists(root)) return [];
  return fs.readdirSync(root, { withFileTypes: true }).flatMap((entry) => {
    const full = path.join(root, entry.name);
    if (entry.isDirectory()) return listFiles(full).map((p) => path.join(entry.name, p));
    return [entry.name];
  });
}

function verifyNativeEntry(file, platform) {
  const text = read(file);
  const found = WEB_ONLY_MARKERS.filter((marker) => text.includes(marker));
  if (found.length) {
    throw new Error(`${platform} native entry ${path.relative(ROOT, file)} contains Web-only markers: ${found.join(", ")}`);
  }
}

function copyPath(source, target) {
  const stat = fs.statSync(source);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.cpSync(source, target, { recursive: stat.isDirectory(), force: true });
}

function verifyPathEqual(a, b, label) {
  if (!exists(a) || !exists(b)) throw new Error(`${label}: missing path`);
  const aStat = fs.statSync(a);
  const bStat = fs.statSync(b);
  if (aStat.isDirectory() !== bStat.isDirectory()) {
    throw new Error(`${label}: file/directory type mismatch`);
  }
  if (aStat.isDirectory()) {
    const aFiles = listFiles(a).sort();
    const bFiles = listFiles(b).sort();
    if (aFiles.join("\\n") !== bFiles.join("\\n")) {
      throw new Error(`${label}: directory listing mismatch`);
    }
    for (const rel of aFiles) verifyPathEqual(path.join(a, rel), path.join(b, rel), `${label}/${rel}`);
    return;
  }
  if (Buffer.compare(fs.readFileSync(a), fs.readFileSync(b)) !== 0) {
    throw new Error(`${label}: byte mismatch (${path.relative(ROOT, a)} vs ${path.relative(ROOT, b)})`);
  }
}

function validateSources() {
  for (const platform of PLATFORMS) {
    const nativeRoot = path.join(ROOT, "native-shell", platform.name, "public");
    for (const entry of ENTRY_FILES) {
      const source = path.join(nativeRoot, entry);
      if (!exists(source)) throw new Error(`${platform.name}: missing native-shell entry ${entry}`);
      verifyNativeEntry(source, platform.name);
    }
    for (const rel of SAFE_SHARED_PATHS) {
      const source = path.join(WEB, rel);
      if (!exists(source)) throw new Error(`Missing allowlisted shared asset: public/${rel}`);
    }
  }
}

function verifyBundle(platform, bundleRoot) {
  const nativeSource = path.join(ROOT, "native-shell", platform.name, "public");
  for (const entry of ENTRY_FILES) {
    const source = path.join(nativeSource, entry);
    const target = path.join(bundleRoot, entry);
    verifyNativeEntry(target, platform.name);
    verifyPathEqual(source, target, `${platform.name} ${entry}`);
  }
  for (const rel of SAFE_SHARED_PATHS) {
    verifyPathEqual(path.join(WEB, rel), path.join(bundleRoot, rel), `${platform.name} ${rel}`);
  }
}

function bridgeFiles(bundleRoot) {
  return [...PRESERVE_FILES].filter((name) => exists(path.join(bundleRoot, name)));
}

function synchronize(platform) {
  const nativeSource = path.join(ROOT, "native-shell", platform.name, "public");
  const destination = platform.destination;

  if (CHECK_ONLY) {
    verifyBundle(platform, destination);
    console.log(`${platform.name}: checked filtered native bundle; preserved ${bridgeFiles(destination).length} bridge files`);
    return;
  }

  // Build and validate a complete staged copy first. The final directory swap
  // is same-filesystem rename-based, so a failed validation never leaves a
  // partially synchronized platform bundle behind.
  const parent = path.dirname(destination);
  const stage = path.join(parent, `.muchi-native-stage-${platform.name}-${process.pid}`);
  const backup = path.join(parent, `.muchi-native-before-${platform.name}-${process.pid}`);
  // Do not erase a leftover stage/backup from a prior failed run. It may
  // contain a user's original native assets and must be reviewed manually.
  if (exists(stage) || exists(backup)) {
    throw new Error(`${platform.name}: native sync staging path already exists`);
  }
  fs.mkdirSync(parent, { recursive: true });
  if (exists(destination)) fs.cpSync(destination, stage, { recursive: true, force: true });
  else fs.mkdirSync(stage, { recursive: true });

  try {
    for (const entry of ENTRY_FILES) {
      copyPath(path.join(nativeSource, entry), path.join(stage, entry));
    }
    for (const rel of SAFE_SHARED_PATHS) {
      copyPath(path.join(WEB, rel), path.join(stage, rel));
    }
    // The allowlist limits newly copied assets. Existing destination files
    // are preserved even when they are not present in the release package.

    verifyBundle(platform, stage);

    let oldMoved = false;
    let newMoved = false;
    try {
      if (exists(destination)) {
        fs.renameSync(destination, backup);
        oldMoved = true;
      }
      fs.renameSync(stage, destination);
      newMoved = true;
      // Validate the installed path before deleting the rollback copy.
      verifyBundle(platform, destination);
      if (exists(backup)) fs.rmSync(backup, { recursive: true, force: true });
    } catch (error) {
      if (newMoved && exists(destination)) fs.rmSync(destination, { recursive: true, force: true });
      if (oldMoved && exists(backup)) fs.renameSync(backup, destination);
      throw error;
    }
  } catch (error) {
    fs.rmSync(stage, { recursive: true, force: true });
    // A remaining backup may be the only copy of the original bundle if a
    // rollback failed; leave it in place for manual recovery.
    throw error;
  }

  console.log(`${platform.name}: synchronized filtered native bundle atomically; preserved ${bridgeFiles(destination).length} bridge files`);
}

validateSources();
for (const platform of PLATFORMS) synchronize(platform);
console.log(`Native bundle ${CHECK_ONLY ? "check" : "sync"} PASS`);
